import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createOrder} from '../src/order.mjs';

test('hidden check', async () => {
  for (const price of [-1, 10.5, '1000', null]) assert.throws(() => createOrder({items: [{price, quantity: 1}]}), /invalid_price/);
  assert.equal(createOrder({items: [{price: 0, quantity: 1}]}).subtotal, 0);
});
